) VALUES (
  'ccar-p',
  'Claude Certified Architect — Professional',
  'CCAR-P',
  'Chinh phục chứng chỉ cấp cao Claude Certified Architect (Professional). Thiết kế hệ thống AI quy mô doanh nghiệp, quản trị rủi ro & an toàn bảo mật, tối ưu hóa độ trễ/chi phí và điều phối tác nhân đa luồng.',
  'Nâng cao',
  '18-24 Giờ',
  'bg-gradient-to-br from-orange-700 via-red-800 to-slate-950 text-white',
  'ShieldCheck',
  false,
  true,
  'new'
) ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  code = EXCLUDED.code,
  description = EXCLUDED.description,
  difficulty = EXCLUDED.difficulty,
  estimated_hours = EXCLUDED.estimated_hours,
